use serde_json::json;
use wardrobe_core::Application;
#[test]
fn explicit_recognition_records_selected_provider_and_images_without_changing_manual_facts() {
    let dir=tempfile::tempdir().unwrap();let app=Application::open(&dir.path().join("db")).unwrap();let path=dir.path().join("generated.png");image::RgbImage::from_pixel(16,16,image::Rgb([240,240,240])).save(&path).unwrap();
    let clothing=app.execute("clothing.create",json!({"member_id":"default","name":"我的手工名称","category":"top"})).unwrap();let asset=app.execute("assets.import",json!({"member_id":"default","path":path})).unwrap();app.execute("assets.adopt",json!({"member_id":"default","clothing_id":clothing["id"],"asset_id":asset["id"]})).unwrap();
    let provider=app.execute("provider.save",json!({"name":"本地视觉","endpoint":"http://127.0.0.1:18083/v1","model":"wardrobe-smolvlm","capabilities":["vision"],"authentication":"none"})).unwrap();
    let input=json!({"member_id":"default","operation_key":"explicit-analysis","provider_id":provider["id"],"clothing_id":clothing["id"],"asset_ids":[asset["id"]],"upload_role":"product_display","confirm_upload":true});let created=app.execute("recognition.create",input.clone()).unwrap();assert_eq!(created["state"],"queued");assert_eq!(created["payload"]["provider"]["model"],"wardrobe-smolvlm");assert_eq!(created["payload"]["asset_ids"],json!([asset["id"]]));assert_eq!(app.execute("recognition.create",input).unwrap(),created);
    assert_eq!(app.execute("clothing.get",json!({"member_id":"default","id":clothing["id"]})).unwrap()["name"],"我的手工名称");
}

#[test]
fn actual_http_proposal_requires_review_and_reanalysis_preserves_manual_edits() {
 use std::io::{Read,Write};
 let listener=std::net::TcpListener::bind("127.0.0.1:0").unwrap();let endpoint=format!("http://{}/v1",listener.local_addr().unwrap());
 let server=std::thread::spawn(move||{let(mut s,_)=listener.accept().unwrap();let mut b=vec![];loop{let mut chunk=[0;4096];let n=s.read(&mut chunk).unwrap();assert!(n>0);b.extend_from_slice(&chunk[..n]);if let Some(split)=b.windows(4).position(|w|w==b"\r\n\r\n"){let h=String::from_utf8_lossy(&b[..split]);let len:usize=h.lines().find_map(|l|l.to_lowercase().strip_prefix("content-length: ").map(|v|v.parse().unwrap())).unwrap();if b.len()>=split+4+len{let req:serde_json::Value=serde_json::from_slice(&b[split+4..split+4+len]).unwrap();assert_eq!(req["model"],"http-fixture");assert!(req["messages"][0]["content"][1]["image_url"]["url"].as_str().unwrap().starts_with("data:image/webp;base64,"));break;}}}let body=json!({"model":"http-fixture","choices":[{"message":{"content":"White shirt; material and brand cannot be established."}}],"usage":{"prompt_tokens":25,"completion_tokens":12}}).to_string();write!(s,"HTTP/1.1 200 OK\r\nContent-Length: {}\r\nContent-Type: application/json\r\nConnection: close\r\n\r\n{}",body.len(),body).unwrap();});
 let dir=tempfile::tempdir().unwrap();let app=Application::open(&dir.path().join("db")).unwrap();let path=dir.path().join("test.png");image::RgbImage::new(16,16).save(&path).unwrap();let c=app.execute("clothing.create",json!({"member_id":"default","name":"手工","category":"top"})).unwrap();let a=app.execute("assets.import",json!({"member_id":"default","path":path})).unwrap();app.execute("assets.adopt",json!({"member_id":"default","clothing_id":c["id"],"asset_id":a["id"]})).unwrap();let p=app.execute("provider.save",json!({"name":"HTTP fixture","endpoint":endpoint,"model":"http-fixture","capabilities":["vision"],"authentication":"none"})).unwrap();let j=app.execute("recognition.create",json!({"member_id":"default","clothing_id":c["id"],"asset_ids":[a["id"]],"provider_id":p["id"],"confirm_upload":true,"upload_role":"product_display","operation_key":"review"})).unwrap();
 let done=app.execute("recognition.process",json!({"member_id":"default","id":j["id"]})).unwrap();server.join().unwrap();assert_eq!(done["state"],"succeeded");let suggestion=app.execute("recognition.get",json!({"member_id":"default","id":done["result"]["suggestion_id"]})).unwrap();assert_eq!(suggestion["state"],"pending_review");assert_eq!(suggestion["provenance"]["model"],"http-fixture");assert_eq!(suggestion["raw_text"],"White shirt; material and brand cannot be established.");assert_eq!(app.execute("clothing.get",json!({"member_id":"default","id":c["id"]})).unwrap()["name"],"手工");
 app.execute("clothing.update",json!({"member_id":"default","id":c["id"],"name":"后改手工"})).unwrap();let err=app.execute("recognition.review",json!({"member_id":"default","id":suggestion["id"],"facts":{"description":"白衬衫"},"confirm_review":true})).unwrap_err();assert_eq!(err.code,"review_conflict");assert_eq!(app.execute("clothing.get",json!({"member_id":"default","id":c["id"]})).unwrap()["name"],"后改手工");
}
